# --- measurement-device-independent QKD: Alice and Bob each send a BB84 state to an UNTRUSTED relay Charlie, who performs a Bell-state measurement and announces the outcome.
# Detector side channels of Charlie cannot leak the key, because the key is encoded in the correlation between Alice's and Bob's states, not in anything Charlie measures about one party alone.
def bsm_outcomes(state_ab):
    # projective Bell measurement on the two sent qubits: probabilities and post-measurement information
    return {name: float((v.conj() @ state_ab @ v).real) for name, v in BELL.items()}
def basis_state(bit, basis):
    return ket([bit]) if basis == "Z" else (ket([0]) + (-1) ** bit * ket([1])) / math.sqrt(2)
print("Bell-state measurement outcomes for the BB84 state pairs sent by Alice (first) and Bob (second):")
print(f"{'basis':>6} {'(bit a, bit b)':>15} " + " ".join(f"{n:>8}" for n in BELL))
table = {}
for basis in ("Z", "X"):
    for a, b in itertools.product((0, 1), repeat=2):
        psi = np.kron(basis_state(a, basis), basis_state(b, basis))
        probs = bsm_outcomes(proj(psi)); table[(basis, a, b)] = probs
        print(f"{basis:>6} {str((a, b)):>15} " + " ".join(f"{p:>8.3f}" for p in probs.values()))
print()
print("what the outcome announced by Charlie tells Alice and Bob about the relation of their bits (in matching bases):")
for outcome in ("psi+", "psi-", "phi+", "phi-"):
    relation = {}
    for basis in ("Z", "X"):
        possible = [(a, b) for a in (0, 1) for b in (0, 1) if table[(basis, a, b)][outcome] > 1e-9]
        parities = {(a ^ b) for a, b in possible}
        relation[basis] = f"a xor b = {parities.pop()}" if len(parities) == 1 else "no relation"
    print(f"  Charlie announces {outcome}: Z basis -> {relation['Z']}; X basis -> {relation['X']}")
print("so for each announced outcome the two bits of Alice and Bob in the same basis are perfectly correlated or perfectly anticorrelated, and Bob flips his bit when told: Alice and Bob obtain a shared key without trusting Charlie's equipment, and Charlie learns only the XOR-type relation, which is public anyway")
# --- Charlie cheats: announcing random outcomes does not help him learn the bits; he only causes errors (a failed correlation) that Alice and Bob see in their test rounds
rng = np.random.default_rng(65)
n = 40000
honest_errors = cheating_errors = tested = 0
for _ in range(n):
    basis = "Z" if rng.random() < 0.5 else "X"
    a, b = rng.integers(0, 2, 2)
    probs = table[(basis, a, b)]
    names = list(probs)
    outcome = names[rng.choice(4, p=[probs[k] for k in names])]
    fake = names[rng.integers(0, 4)]
    def predicted_relation(out):
        poss = [(x, y) for x in (0, 1) for y in (0, 1) if table[(basis, x, y)][out] > 1e-9]
        return poss[0][0] ^ poss[0][1]
    tested += 1
    honest_errors += (a ^ b) != predicted_relation(outcome)
    cheating_errors += (a ^ b) != predicted_relation(fake)
print(f"over {tested:,} rounds: error rate with Charlie's honest announcements {honest_errors / tested:.4f}; with random fake announcements {cheating_errors / tested:.4f} (a cheating relay produces a visible error rate of about 1/2, so he cannot cheat undetected)")
print("MDI-QKD removes all detector vulnerabilities from the security analysis (the attacks that blind or control single-photon detectors, 6.7) at the cost of a much lower rate: a two-photon coincidence at the relay is needed, and the key rate scales with the transmission of the two half-links; twin-field QKD (a related scheme) reaches a rate scaling like the square root of the channel transmission (from the literature)")

from dataclasses import dataclass

# A rule-based comparison of PQC and QKD for a given deployment. Every rule below states a property established in modules B9 to B11, C5 and C6; the engine explains each verdict.
@dataclass
class Scenario:
    name: str
    needs_signatures: bool          # authentication of identities, software or documents is required
    endpoints: str                  # "many" (internet scale), "few" (a handful of fixed sites), "devices" (constrained, no fibre)
    max_link_km: float              # the longest single link between two parties
    dedicated_fibre: bool           # dark fibre or a dedicated wavelength is available end to end
    software_only: bool             # the solution must be deployable by software update on existing hardware
    relays_trusted: bool            # intermediate nodes may hold keys in the clear

def assess(s):
    verdicts = {}
    # PQC (ML-KEM key establishment, ML-DSA / SLH-DSA signatures): software, works over any network, signatures available (FIPS 203, 204, 205); security is computational
    reasons = ["runs as software on existing hardware and over the existing internet", "provides both key establishment (ML-KEM) and signatures (ML-DSA, SLH-DSA)", "security is computational: it rests on the hardness of lattice and hash problems"]
    verdicts["PQC (ML-KEM + ML-DSA / SLH-DSA)"] = ("applicable", reasons)
    # QKD point to point
    why, ok = [], True
    if s.needs_signatures: ok = False; why.append("QKD provides no digital signatures or identity: signatures still need PQC or classical algorithms")
    if s.endpoints == "many": ok = False; why.append("QKD links join device pairs: it does not scale to internet-scale numbers of endpoints")
    if s.endpoints == "devices": ok = False; why.append("constrained devices without dedicated fibre cannot host QKD hardware")
    if s.max_link_km > 100: ok = False; why.append(f"a {s.max_link_km:.0f} km fibre link is beyond the practical range of a direct QKD link in the lesson's model (about 200 km at best, with low rates)")
    if not s.dedicated_fibre: ok = False; why.append("needs dedicated fibre or wavelength")
    if s.software_only: ok = False; why.append("needs specialised hardware: not a software update")
    if ok: why.append("short, dedicated, fixed link between few sites: the use case QKD was built for; it still needs authentication of the classical channel")
    verdicts["QKD point to point"] = ("applicable" if ok else "not suitable", why)
    # QKD with trusted nodes
    why, ok = [], True
    if s.needs_signatures: ok = False; why.append("no signatures")
    if s.endpoints != "few": ok = False; why.append("only for a handful of fixed sites")
    if s.max_link_km <= 100 and ok: ok = False; why.append("no relay needed: the span fits one direct link (point-to-point QKD above)")
    if s.max_link_km > 100 and not s.relays_trusted: ok = False; why.append("distance beyond one link needs trusted relay nodes, which the scenario does not accept")
    if not s.dedicated_fibre: ok = False; why.append("needs dedicated fibre")
    if s.software_only: ok = False; why.append("not a software update")
    if ok: why.append("a chain of QKD links with trusted nodes can span the distance; each relay holds the keys in the clear")
    verdicts["QKD with trusted nodes"] = ("applicable" if ok else "not suitable", why)
    # hybrid: PQC combined with QKD keys
    base_ok = verdicts["QKD point to point"][0] == "applicable" or verdicts["QKD with trusted nodes"][0] == "applicable"
    verdicts["PQC + QKD hybrid"] = ("applicable" if base_ok else "not applicable (QKD part unavailable)", ["session keys derived from both sources are secure if either holds (module C6.9); adds cost and complexity", "PQC still supplies authentication and the large-scale deployment path"] if base_ok else ["there is no QKD component to combine"])
    return verdicts

scenarios = [
    Scenario("web service for millions of clients", True, "many", 10000, False, True, False),
    Scenario("data-centre interconnect, two sites 60 km apart, dark fibre", False, "few", 60, True, False, True),
    Scenario("software update signing for devices in the field", True, "devices", 0, False, True, False),
    Scenario("two government sites 800 km apart, dedicated fibre", False, "few", 800, True, False, False),
    Scenario("same, relay nodes in secured facilities", False, "few", 800, True, False, True),
    Scenario("mobile app and cloud backend", True, "many", 10000, False, True, False),
]
for s in scenarios:
    print(f"== {s.name}")
    for option, (verdict, why) in assess(s).items():
        print(f"   {option:<34} {verdict}")
        for w in why:
            print(f"        - {w}")
